#define main pure_rho_reference_actual_not_invoked
#include "test_rho_log_actual.cpp"
#undef main
#include "z4c/hyperboloidal/bounded_rho_log_derivative.hpp"
using Bounded=h::BoundedRhoLogDerivative;
int main(int argc,char **argv){Kokkos::initialize(argc,argv);int status=0;try{
  if(argc!=2)throw std::invalid_argument("usage actual initial.dat");const auto start=std::chrono::steady_clock::now();auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);h::PuncturePosition point;std::cout<<std::setprecision(17);
  const auto before=std::chrono::steady_clock::now();h::PunctureLogValuePlans halo(grid,point,.24,20000,8,175);const Real cache_seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-before).count();V stored(2*initial.size()),chi(grid.count,0),alpha(grid.count,0);
  for(size_t p=0;p<initial.size();++p){chi[grid.active[p]]=stored[2*p]=std::log(initial[p].chi);alpha[grid.active[p]]=stored[2*p+1]=std::log(initial[p].alpha)-std::log(Chart(grid.geometry[p].x,1).reference.value);}grid.Fill(chi,1);grid.Fill(alpha,1);halo.FillPositiveLogs(chi,alpha,point);V padded(2*grid.count);for(int i=0;i<grid.count;++i){padded[i]=chi[i];padded[grid.count+i]=alpha[i];}h::PunctureLogPlans base(grid,point);
  auto H=[&](size_t p,const S&q){const Real omega=(1-initial[p].r*initial[p].r)/2;return HChi(grid.geometry[p].x,q)+(2./3)*initial[p].khat*initial[p].khat-1.5*omega*omega*initial[p].arr*initial[p].arr;};
  V fdH(initial.size()),baseH(initial.size()),rawH(initial.size()),boundedH(initial.size());for(size_t p=0;p<initial.size();++p)fdH[p]=baseH[p]=rawH[p]=boundedH[p]=H(p,Sample(grid,padded,stored,p,0));
  size_t raw_ready=0,bounded_ready=0,mixed=0,strict_rejected=0;Real minimum_theta=1,maximum_reproduction=0,max_g=0,max_dd=0,max_noise=0;std::map<std::string,size_t>unsupported;
  for(const auto &row:base.rows){const size_t p=row.active;const auto &x=grid.geometry[p].x;const Real dx=Spacing(grid,p);std::vector<Single::Point> nodes;for(size_t donor:row.donors){const auto &d=grid.geometry[donor].x;nodes.push_back({d[0],d[1],d[2]});}
    Single raw;Single::Options options;options.maximum_gradient_l1=options.maximum_hessian_l1=1e9;const bool raw_ok=raw.Build({x[0],x[1],x[2]},nodes,dx,point,options);raw_ready+=raw_ok;
    Bounded bounded;const bool bounded_ok=bounded.Build({x[0],x[1],x[2]},nodes,dx,point);bounded_ready+=bounded_ok;if(!bounded_ok){++unsupported[bounded.diagnostics().status];boundedH[p]=std::numeric_limits<Real>::quiet_NaN();}if(!raw_ok)rawH[p]=std::numeric_limits<Real>::quiet_NaN();
    bool strict=false;if(raw_ok){const auto &d=raw.diagnostics();strict=d.value_weight_l1<=16&&d.scaled_gradient_weight_l1<=32&&d.scaled_hessian_weight_l1<=64;strict_rejected+=!strict;}
    WeightAudit audit;if(bounded_ok){const auto &d=bounded.diagnostics();minimum_theta=std::min(minimum_theta,d.theta);mixed+=d.theta<1;maximum_reproduction=std::max(maximum_reproduction,d.reproduction);audit=AuditActual(bounded,dx,point,row.donors.size());max_g=std::max(max_g,audit.gradient);max_dd=std::max(max_dd,audit.hessian);if(audit.value>16+1e-10||audit.gradient>32+1e-10||audit.hessian>64+1e-10)throw std::runtime_error("independent blend functional caps fail");}
    for(int f=0;f<2;++f){V values;for(size_t donor:row.donors)values.push_back(stored[2*donor+f]);const auto bq=base.Sample(row,stored,2,f);S rq{},cq{};if(raw_ok)rq=EvaluateActual(raw,values,stored[2*p+f],point);if(bounded_ok){cq=EvaluateActual(bounded,values,stored[2*p+f],point);max_noise=std::max(max_noise,NoiseActual(bounded,values,cq,dx,point,audit));}
      if(f==0){baseH[p]=H(p,bq);if(raw_ok)rawH[p]=H(p,rq);if(bounded_ok)boundedH[p]=H(p,cq);}
      if(p==34919){const auto exact=ExactInner(x,f);std::cout<<"{\"phase\":\"target34919\",\"field\":\""<<(f==0?"chi":"alpha")<<"\",\"bounded_ready\":"<<bounded_ok<<",\"theta\":"<<(bounded_ok?bounded.diagnostics().theta:-1)<<",\"base_scaled_error\":"<<JetError(bq,exact,dx)<<",\"raw_scaled_error\":"<<(raw_ok?JetError(rq,exact,dx):-1)<<",\"bounded_scaled_error\":"<<(bounded_ok?JetError(cq,exact,dx):-1);if(f==0)std::cout<<",\"base_H\":"<<baseH[p]<<",\"raw_H\":"<<rawH[p]<<",\"bounded_H\":"<<boundedH[p];std::cout<<"}\n";}
    }
    std::cout<<"{\"phase\":\"row\",\"point\":"<<p<<",\"bounded_ready\":"<<bounded_ok<<",\"strict_pure_rho_ready\":"<<strict<<",\"rho_over_h\":"<<initial[p].r/dx<<",\"theta\":"<<(bounded_ok?bounded.diagnostics().theta:-1)<<",\"gradient_l1\":"<<audit.gradient<<",\"hessian_l1\":"<<audit.hessian<<",\"common_space_reproduction\":"<<(bounded_ok?bounded.diagnostics().reproduction:-1)<<"}\n";
  }
  std::cout<<"{\"phase\":\"summary\",\"all_active_cells\":"<<initial.size()<<",\"selected_rows\":"<<base.rows.size()<<",\"raw_ready\":"<<raw_ready<<",\"bounded_ready\":"<<bounded_ready<<",\"mixed_theta_rows\":"<<mixed<<",\"minimum_theta\":"<<minimum_theta<<",\"strict_pure_rho_rejections\":"<<strict_rejected<<",\"maximum_gradient_l1\":"<<max_g<<",\"maximum_hessian_l1\":"<<max_dd<<",\"maximum_common_space_reproduction\":"<<maximum_reproduction<<",\"maximum_scaled_noise\":"<<max_noise<<",\"profiles\":{";
  const V*profile[4]={&fdH,&baseH,&rawH,&boundedH};const char*name[4]={"mapped_FD","base","rho_raw","bounded_blend"};const bool complete[4]={true,true,raw_ready==base.rows.size(),bounded_ready==base.rows.size()};
  for(int b=0;b<4;++b){if(b)std::cout<<',';std::cout<<'"'<<name[b]<<"\":{\"complete\":"<<complete[b]<<",\"all\":";if(!complete[b])std::cout<<"null,\"core\":null}";else{Norm all,core;for(size_t p=0;p<initial.size();++p){const Real w=grid.volumes[p]/std::pow(initial[p].chi,1.5);all.Add(p,w,(*profile[b])[p]);if(initial[p].r<.12)core.Add(p,w,(*profile[b])[p]);}all.Print();std::cout<<",\"core\":";core.Print();std::cout<<'}';}}
  std::cout<<"},\"unsupported\":{";bool first=true;for(const auto &r:unsupported){if(!first)std::cout<<',';first=false;std::cout<<'"'<<r.first<<"\":"<<r.second;}std::cout<<"},\"halo_build_seconds\":"<<cache_seconds<<",\"total_seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<",\"active_values_changed\":false,\"caps_unchanged_16_32_64\":true,\"unsupported_rows_have_no_fallback\":true,\"production_adopted\":false}\n";
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
